from ledger import positions_for; import unittest

class TestEdgeCases(unittest.TestCase):
    def test_multiple_retractions_same_posting(self):
        # Test that multiple retractions of the same posting only cancel once
        result = positions_for([
            {'key': 'p1', 'kind': 'post', 'bucket': 'cash', 'delta': 10},
            {'key': 'r1', 'kind': 'retract', 'reference': 'p1'},
            {'key': 'r2', 'kind': 'retract', 'reference': 'p1'}
        ])
        self.assertEqual(result, {'cash': 0})

    def test_retraction_before_posting(self):
        # Test that retraction before posting doesn't cause issues
        result = positions_for([
            {'key': 'r1', 'kind': 'retract', 'reference': 'p1'},
            {'key': 'p1', 'kind': 'post', 'bucket': 'cash', 'delta': 10}
        ])
        self.assertEqual(result, {'cash': 10})

    def test_retraction_of_nonexistent_posting(self):
        # Test that retraction of non-existent posting has no effect
        result = positions_for([
            {'key': 'r1', 'kind': 'retract', 'reference': 'p1'}
        ])
        self.assertEqual(result, {})

    def test_multiple_independent_postings(self):
        # Test multiple independent postings and retractions
        result = positions_for([
            {'key': 'p1', 'kind': 'post', 'bucket': 'cash', 'delta': 7},
            {'key': 'p2', 'kind': 'post', 'bucket': 'cash', 'delta': -2},
            {'key': 'r1', 'kind': 'retract', 'reference': 'p1'}
        ])
        self.assertEqual(result, {'cash': -2})

if __name__ == '__main__':
    unittest.main()

